<script setup lang="ts">
import {computed,shallowRef,watch} from 'vue'
import {Modal as AModal,Descriptions as ADescriptions,DescriptionsItem as ADescriptionsItem,InputNumber as AInputNumber} from 'ant-design-vue'
import StatePanel from './StatePanel.vue'
import {watchlistKinds,watchlistMatchTypes,type WatchlistRecord} from '../watchlists'
import {formatTime} from '../types'
const props=defineProps<{record:WatchlistRecord|null;pending?:boolean;error?:string;revision:number;maximum:number}>()
const emit=defineEmits<{close:[];read:[revision:number]}>()
const choice=shallowRef<number|null>(props.revision),validChoice=computed(()=>choice.value!==null&&Number.isSafeInteger(choice.value)&&choice.value>=1&&choice.value<=props.maximum)
watch(()=>props.revision,v=>{choice.value=v})
function read(){if(!props.pending&&validChoice.value&&choice.value!==null)emit('read',choice.value)}
function choose(v:number|string|null){choice.value=v===null||v===''?null:Number(v)}
</script>
<template><a-modal :open="true" title="名单详情与修订" :width="820" :body-style="{maxHeight:'calc(100vh - 240px)',overflowY:'auto'}" @cancel="emit('close')"><div class="watchlist-revision"><label for="watchlist-revision">读取修订</label><a-input-number id="watchlist-revision" :value="choice??''" @update:value="choose" :min="1" :max="maximum" :precision="0" :disabled="pending"/><a-button :loading="pending" :disabled="pending||!validChoice" @click="read">读取</a-button></div><StatePanel :loading="pending" :error="error" @retry="emit('read',revision)"><a-descriptions v-if="record" bordered :column="1" size="small"><a-descriptions-item label="名单">{{record.name}} / <span class="technical">{{record.id}}</span></a-descriptions-item><a-descriptions-item label="修订 / 配置状态">{{record.revision}} / {{record.active?'启用':'停用'}}；历史状态不表示当前仍生效。</a-descriptions-item><a-descriptions-item label="类型 / 匹配">{{watchlistKinds[record.definition.kind]}} / {{watchlistMatchTypes[record.definition.match_type]}}</a-descriptions-item><a-descriptions-item label="匹配值"><pre class="watchlist-values technical">{{record.definition.values.join('\n')}}</pre></a-descriptions-item><a-descriptions-item label="固定探针注册"><ul class="watchlist-scopes"><li v-for="scope in record.definition.sensors" :key="scope.sensor_id"><span class="technical">{{scope.sensor_id}} / {{scope.registration_id}}</span></li></ul></a-descriptions-item><a-descriptions-item label="业务生效（UTC）">{{record.definition.valid_from}}</a-descriptions-item><a-descriptions-item label="业务到期（UTC）">{{record.definition.valid_until}}</a-descriptions-item><a-descriptions-item label="配置依据">{{record.description}}</a-descriptions-item><a-descriptions-item label="保存时间 / 操作者">{{formatTime(record.created_at)}} / {{record.created_by}}</a-descriptions-item><a-descriptions-item label="定义 SHA-256"><span class="technical">{{record.definition_sha256}}</span></a-descriptions-item><a-descriptions-item label="历史保留截止">{{formatTime(record.expires_at)}}；当前配置受引用保护。</a-descriptions-item></a-descriptions></StatePanel><p class="page-description section-gap">修订用于核对当时的定义和状态；名单到期、停用或观察命中均不会删除既有告警事实。</p><template #footer><a-button @click="emit('close')">关闭</a-button></template></a-modal></template>
<style scoped>.watchlist-revision{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.watchlist-values{white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.watchlist-scopes{list-style:none;padding:0;margin:0;display:grid;gap:4px}:deep(.ant-descriptions-item-content){overflow-wrap:anywhere}</style>
